import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","link":"/life/english/new-concept/book-1/review-part-16"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","link":"/life/english/new-concept/book-1/review-part-18"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","link":"/life/english/new-concept/book-1/review-part-16"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","link":"/life/english/new-concept/book-1/review-part-18"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-17.md","filePath":"life/english/new-concept/book-1/review-part-17.md"}'),n={name:"life/english/new-concept/book-1/review-part-17.md"};function i(r,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第116–122课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第116–122课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第116–122课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第116–122课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-116-·-复合不定代词" tabindex="-1">Lesson 116 · 复合不定代词 <a class="header-anchor" href="#lesson-116-·-复合不定代词" aria-label="Permalink to &quot;Lesson 116 · 复合不定代词 {#lesson-116-·-复合不定代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There is nothing unusual in the box.</p><h3 id="练习-1-115" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-115" aria-label="Permalink to &quot;练习 1 {#练习-1-115}&quot;">​</a></h3><p>排序：useful / something.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> something useful</p><p><strong>解析：</strong> 按本课规则判断：someone、anyone、everyone、no one 指人，something、anything、everything、nothing 指事物。作主语时通常视作单数，后用 is/has 等。形容词修饰它们时放在后面，如 something useful。nothing 和 no one 已含否定意义，标准英语通常不再加 not。some/any 的选择仍要结合肯定、否定、请求等语境。</p></details><p><strong>表达迁移：</strong> 围绕“表达有人、无人和不确定对象”写两至三句，再读给同伴听。至少使用一次复合不定代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>There is nothing unusual in the box. Someone is waiting at the side door.</p><p>There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。 Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-116">回看本课</a></p><h2 id="lesson-117-·-过去进行时" tabindex="-1">Lesson 117 · 过去进行时 <a class="header-anchor" href="#lesson-117-·-过去进行时" aria-label="Permalink to &quot;Lesson 117 · 过去进行时 {#lesson-117-·-过去进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was making breakfast when the lights went out.</p><h3 id="练习-1-116" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-116" aria-label="Permalink to &quot;练习 1 {#练习-1-116}&quot;">​</a></h3><p>填 be：I ___ making breakfast when the lights went out.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> was</p><p><strong>解析：</strong> 按本课规则判断：过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去某一时刻正在进行的活动”写两至三句，再读给同伴听。至少使用一次过去进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was making breakfast when the lights went out. They were waiting outside at eight yesterday.</p><p>Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。 Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">回看本课</a></p><h2 id="lesson-118-·-过去进行时" tabindex="-1">Lesson 118 · 过去进行时 <a class="header-anchor" href="#lesson-118-·-过去进行时" aria-label="Permalink to &quot;Lesson 118 · 过去进行时 {#lesson-118-·-过去进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> They were waiting outside at eight yesterday.</p><h3 id="练习-1-117" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-117" aria-label="Permalink to &quot;练习 1 {#练习-1-117}&quot;">​</a></h3><p>填 be：They ___ waiting at eight yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去某一时刻正在进行的活动”写两至三句，再读给同伴听。至少使用一次过去进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>They were waiting outside at eight yesterday. I was making breakfast when the lights went out.</p><p>Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。 Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-118">回看本课</a></p><h2 id="lesson-119-·-过去完成时" tabindex="-1">Lesson 119 · 过去完成时 <a class="header-anchor" href="#lesson-119-·-过去完成时" aria-label="Permalink to &quot;Lesson 119 · 过去完成时 {#lesson-119-·-过去完成时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time we arrived, the museum had closed.</p><h3 id="练习-1-118" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-118" aria-label="Permalink to &quot;练习 1 {#练习-1-118}&quot;">​</a></h3><p>补助动词：The museum ___ closed before we arrived.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p></details><p><strong>表达迁移：</strong> 围绕“说明两个过去事件的先后”写两至三句，再读给同伴听。至少使用一次过去完成时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By the time we arrived, the museum had closed. She had saved the file before the computer stopped.</p><p>We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。 Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-119">回看本课</a></p><h2 id="lesson-120-·-过去完成时" tabindex="-1">Lesson 120 · 过去完成时 <a class="header-anchor" href="#lesson-120-·-过去完成时" aria-label="Permalink to &quot;Lesson 120 · 过去完成时 {#lesson-120-·-过去完成时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She had saved the file before the computer stopped.</p><h3 id="练习-1-119" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-119" aria-label="Permalink to &quot;练习 1 {#练习-1-119}&quot;">​</a></h3><p>按例句判断：先保存文件，还是先电脑停止？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 先保存文件；had saved 表示早于 stopped。</p><p><strong>解析：</strong> 按本课规则判断：过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p></details><p><strong>表达迁移：</strong> 围绕“说明两个过去事件的先后”写两至三句，再读给同伴听。至少使用一次过去完成时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She had saved the file before the computer stopped. By the time we arrived, the museum had closed.</p><p>Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。 We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-120">回看本课</a></p><h2 id="lesson-121-·-关系代词作主语" tabindex="-1">Lesson 121 · 关系代词作主语 <a class="header-anchor" href="#lesson-121-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 121 · 关系代词作主语 {#lesson-121-·-关系代词作主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The woman who lives upstairs is a violinist.</p><h3 id="练习-1-120" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-120" aria-label="Permalink to &quot;练习 1 {#练习-1-120}&quot;">​</a></h3><p>填关系代词（指人作主语）：The woman ___ lives upstairs.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> who（限制性从句也可用 that）</p><p><strong>解析：</strong> 按本课规则判断：定语从句用来修饰前面的名词。指人可用 who，指物可用 which，限制性从句中常可用 that。关系代词在从句中作主语时不能省略，也不能再重复 he/it 等主语。先找先行词，再确定从句缺什么成分，不能只看到中文“的”就机械插入 who。介词短语 in a hat 也可直接修饰人。</p></details><p><strong>表达迁移：</strong> 围绕“通过补充信息识别人或物”写两至三句，再读给同伴听。至少使用一次关系代词作主语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The woman who lives upstairs is a violinist. The lamp that stands by the sofa is broken.</p><p>The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。 The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-121">回看本课</a></p><h2 id="lesson-122-·-关系代词作主语" tabindex="-1">Lesson 122 · 关系代词作主语 <a class="header-anchor" href="#lesson-122-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 122 · 关系代词作主语 {#lesson-122-·-关系代词作主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The lamp that stands by the sofa is broken.</p><h3 id="练习-1-121" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-121" aria-label="Permalink to &quot;练习 1 {#练习-1-121}&quot;">​</a></h3><p>删去重复成分：the lamp that it stands by the sofa.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the lamp that stands by the sofa</p><p><strong>解析：</strong> 按本课规则判断：定语从句用来修饰前面的名词。指人可用 who，指物可用 which，限制性从句中常可用 that。关系代词在从句中作主语时不能省略，也不能再重复 he/it 等主语。先找先行词，再确定从句缺什么成分，不能只看到中文“的”就机械插入 who。介词短语 in a hat 也可直接修饰人。</p></details><p><strong>表达迁移：</strong> 围绕“通过补充信息识别人或物”写两至三句，再读给同伴听。至少使用一次关系代词作主语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The lamp that stands by the sofa is broken. The woman who lives upstairs is a violinist.</p><p>The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。 The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-122">回看本课</a></p>',60)])])}const g=s(n,[["render",i]]);export{m as __pageData,g as default};
